import { createHash } from "node:crypto";

const FORBIDDEN_KEYS = [
  "prompt",
  "messages",
  "body",
  "authorization",
  "apikey",
  "headers",
];

const SECRET_PATTERNS = [
  /\bsk-[A-Za-z0-9_-]{8,}\b/,
  /\bphc_[A-Za-z0-9_-]{8,}\b/,
  /\bghp_[A-Za-z0-9]{8,}\b/,
  /\bAKIA[0-9A-Z]{12,}\b/,
  /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/,
];

const REPRODUCER_KINDS = new Set(["scenario", "route", "command-id"]);
const TRAJECTORY_STATES = new Set(["failure", "success", "rejected", "cancelled"]);

function canonicalJson(value) {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(",")}}`;
}

function digest(value) {
  return `sha256:${createHash("sha256").update(canonicalJson(value)).digest("hex")}`;
}

function normalizedKey(key) {
  return String(key).toLowerCase().replace(/[-_]/g, "");
}

function findLeak(value, path = "$", found = []) {
  if (Array.isArray(value)) {
    value.forEach((item, index) => findLeak(item, `${path}[${index}]`, found));
    return found;
  }
  if (!value || typeof value !== "object") return found;
  for (const [key, child] of Object.entries(value)) {
    const nextPath = `${path}.${key}`;
    const normalized = normalizedKey(key);
    if (FORBIDDEN_KEYS.includes(normalized)) found.push({ path: nextPath, code: "FORBIDDEN_FIELD" });
    findLeak(child, nextPath, found);
  }
  return found;
}

function findSecret(value, path = "$", found = []) {
  if (typeof value === "string") {
    if (SECRET_PATTERNS.some((pattern) => pattern.test(value))) {
      found.push({ path, code: "SECRET_PATTERN" });
    }
    return found;
  }
  if (Array.isArray(value)) {
    value.forEach((item, index) => findSecret(item, `${path}[${index}]`, found));
    return found;
  }
  if (!value || typeof value !== "object") return found;
  for (const [key, child] of Object.entries(value)) findSecret(child, `${path}.${key}`, found);
  return found;
}

function boundedText(value, max = 256) {
  const text = String(value ?? "").trim();
  if (!text || text.length > max) return null;
  if (/[\u0000-\u001f\u007f]/.test(text)) return null;
  return text;
}

function stateOf(trace) {
  const raw = String(trace?.outcome ?? trace?.status ?? trace?.state ?? "").toLowerCase();
  if (raw === "failed" || raw === "fail" || raw === "failure") return "failure";
  if (raw === "rejected" || raw === "reject" || raw === "denied") return "rejected";
  if (raw === "cancelled" || raw === "canceled") return "cancelled";
  if (raw === "success" || raw === "passed" || raw === "pass") return "success";
  return null;
}

function selectorOf(trace) {
  const runId = boundedText(trace?.selector?.runId ?? trace?.runId);
  const attemptValue = trace?.selector?.attempt ?? trace?.attempt;
  const attempt = typeof attemptValue === "number" && Number.isSafeInteger(attemptValue) && attemptValue >= 0
    ? attemptValue
    : null;
  if (!runId || attempt === null) return null;
  return { runId, attempt };
}

function reproducerOf(trace) {
  const source = trace?.reproducer ?? {};
  const kind = String(source.kind ?? "").toLowerCase();
  if (!REPRODUCER_KINDS.has(kind)) return null;
  const id = boundedText(source.id ?? source.target ?? source.route ?? source.commandId ?? source.scenarioId);
  if (!id) return null;
  if (kind === "command-id" && /[\s;&|<>`$]/.test(id)) return null;
  return { kind, id };
}

function isoTime(value) {
  if (value === undefined || value === null) return null;
  const date = value instanceof Date ? value : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

function withinRecentWindow(trace, now, days = 7) {
  const timestamp = isoTime(trace?.timestamp ?? trace?.createdAt ?? trace?.startedAt);
  if (!timestamp) return false;
  const age = now.getTime() - new Date(timestamp).getTime();
  return age >= 0 && age <= days * 24 * 60 * 60 * 1000;
}

function inspectTrace(trace, now = new Date()) {
  if (!trace || typeof trace !== "object" || Array.isArray(trace)) {
    return { rejected: true, code: "INVALID_TRACE", leaks: [] };
  }
  const forbidden = findLeak(trace);
  const secrets = findSecret(trace);
  const leaks = [...forbidden, ...secrets];
  if (leaks.length) return { rejected: true, code: "UNREDACTED_TRACE", leaks };
  const state = stateOf(trace);
  if (!state) return { rejected: true, code: "INVALID_OUTCOME", leaks: [] };
  const selector = selectorOf(trace);
  if (!selector) return { rejected: true, code: "INVALID_SELECTOR", leaks: [] };
  const reproducer = reproducerOf(trace);
  if (!reproducer) return { rejected: true, code: "INVALID_REPRODUCER", leaks: [] };
  if (!withinRecentWindow(trace, now)) return { rejected: true, code: "OUTSIDE_7_DAY_WINDOW", leaks: [] };
  return { rejected: false, code: null, leaks: [], state, selector, reproducer };
}

/**
 * Convert one already-selected, redacted trace into one replayable evaluation sample.
 * The function has no timer, daemon, network, or shell behavior.
 */
export function convertTraceToEvalSample(trace, options = {}) {
  const now = options.now instanceof Date ? options.now : new Date(options.now ?? Date.now());
  const inspection = inspectTrace(trace, now);
  if (inspection.rejected) {
    return {
      sample: null,
      diagnostic: {
        status: "rejected",
        code: inspection.code,
        runId: boundedText(trace?.selector?.runId ?? trace?.runId, 128),
        leaks: inspection.leaks.map(({ path, code }) => ({ path, code })),
      },
    };
  }

  const expected = inspection.state === "failure"
    ? { beforeFix: "fail", afterFix: "pass" }
    : { beforeFix: "pass", afterFix: "pass" };
  const sample = {
    schemaVersion: 1,
    selector: inspection.selector,
    reproducer: inspection.reproducer,
    expected,
  };
  sample.digest = digest(sample);
  return {
    sample,
    diagnostic: {
      status: "converted",
      code: null,
      runId: inspection.selector.runId,
      outcome: inspection.state,
    },
  };
}

/**
 * Explicit batch conversion. Only supplied traces are considered; no discovery is performed.
 */
export function convertSelectedTraces(traces, options = {}) {
  const now = options.now instanceof Date ? options.now : new Date(options.now ?? Date.now());
  const selected = Array.isArray(traces) ? traces : [];
  const samples = [];
  const diagnostics = [];
  for (const trace of selected) {
    const result = convertTraceToEvalSample(trace, { now });
    if (result.sample) samples.push(result.sample);
    diagnostics.push(result.diagnostic);
  }
  return { samples, diagnostics };
}

export function validateTraceRedaction(trace) {
  const inspection = inspectTrace(trace, new Date());
  return {
    valid: !inspection.rejected,
    code: inspection.code,
    leaks: inspection.leaks.map(({ path, code }) => ({ path, code })),
  };
}

export function computeSampleDigest(sample) {
  const copy = { ...sample };
  delete copy.digest;
  return digest(copy);
}

export const TRACE_TO_EVAL_SAMPLE_KINDS = Object.freeze(["scenario", "route", "command-id"]);

const isMain = process.argv[1] && import.meta.url === new URL(`file://${process.argv[1]}`).href;
if (isMain) {
  const input = process.argv[2];
  if (!input) {
    process.stderr.write("usage: trace-to-eval-sample.mjs <selected-traces.json>\n");
    process.exitCode = 2;
  } else {
    const { readFile, writeFile } = await import("node:fs/promises");
    const traces = JSON.parse(await readFile(input, "utf8"));
    const result = convertSelectedTraces(traces);
    const output = process.argv[3];
    const serialized = `${JSON.stringify(result, null, 2)}\n`;
    if (output) await writeFile(output, serialized, { encoding: "utf8", flag: "wx" });
    else process.stdout.write(serialized);
  }
}

export type TraceOutcome = "failure" | "success" | "rejected" | "cancelled";

export type TraceSelector = {
  runId: string;
  attempt: number;
};

export type TraceReproducer = {
  kind: "scenario" | "route" | "command-id";
  id: string;
};

export type EvalExpectation = {
  beforeFix: "fail" | "pass";
  afterFix: "pass";
};

export type EvalSample = {
  schemaVersion: 1;
  selector: TraceSelector;
  reproducer: TraceReproducer;
  expected: EvalExpectation;
  digest: string;
};

export type SelectedTrace = {
  outcome?: TraceOutcome | "failed" | "fail" | "passed" | "pass" | "denied" | "canceled";
  status?: TraceOutcome | "failed" | "fail" | "passed" | "pass" | "denied" | "canceled";
  state?: TraceOutcome;
  runId?: string;
  attempt?: number;
  selector?: Partial<TraceSelector>;
  reproducer?: {
    kind: TraceReproducer["kind"];
    id?: string;
    target?: string;
    route?: string;
    commandId?: string;
    scenarioId?: string;
  };
  timestamp?: string | number | Date;
  createdAt?: string | number | Date;
  startedAt?: string | number | Date;
  [key: string]: unknown;
};

export type ConversionDiagnostic = {
  status: "converted" | "rejected";
  code: "UNREDACTED_TRACE" | "INVALID_TRACE" | "INVALID_OUTCOME" | "INVALID_SELECTOR" | "INVALID_REPRODUCER" | "OUTSIDE_7_DAY_WINDOW" | null;
  runId?: string | null;
  outcome?: TraceOutcome;
  leaks?: Array<{ path: string; code: "FORBIDDEN_FIELD" | "SECRET_PATTERN" }>;
};

export type ConversionResult = {
  sample: EvalSample | null;
  diagnostic: ConversionDiagnostic;
};

export type BatchConversionResult = {
  samples: EvalSample[];
  diagnostics: ConversionDiagnostic[];
};

export type RedactionValidation = {
  valid: boolean;
  code: ConversionDiagnostic["code"];
  leaks: Array<{ path: string; code: "FORBIDDEN_FIELD" | "SECRET_PATTERN" }>;
};

export const TRACE_TO_EVAL_SAMPLE_KINDS: readonly ["scenario", "route", "command-id"];

export function convertTraceToEvalSample(
  trace: SelectedTrace,
  options?: { now?: Date | string | number },
): ConversionResult;

export function convertSelectedTraces(
  traces: SelectedTrace[],
  options?: { now?: Date | string | number },
): BatchConversionResult;

export function validateTraceRedaction(trace: SelectedTrace): RedactionValidation;

export function computeSampleDigest(sample: EvalSample): string;

