export type TraceSelector = {
  runId: string;
  attempt: number;
};

export type TraceReproducer = {
  kind: "scenario" | "route" | "command-id";
  id: string;
};

export type EvalExpectation = {
  beforeFix: "fail" | "pass";
  afterFix: "pass";
};

export type EvalSample = {
  schemaVersion: 1;
  selector: TraceSelector;
  reproducer: TraceReproducer;
  expected: EvalExpectation;
  digest: string;
};

export type SelectedTrace = {
  outcome?: TraceOutcome | "failed" | "fail" | "passed" | "pass" | "denied" | "canceled";
  status?: TraceOutcome | "failed" | "fail" | "passed" | "pass" | "denied" | "canceled";
  state?: TraceOutcome;
  runId?: string;
  attempt?: number;
  selector?: Partial<TraceSelector>;
  reproducer?: {
    kind: TraceReproducer["kind"];
    id?: string;
    target?: string;
    route?: string;
    commandId?: string;
    scenarioId?: string;
  };
  timestamp?: string | number | Date;
  createdAt?: string | number | Date;
  startedAt?: string | number | Date;
  [key: string]: unknown;
};

export type ConversionDiagnostic = {
  status: "converted" | "rejected";
  code: "UNREDACTED_TRACE" | "INVALID_TRACE" | "INVALID_OUTCOME" | "INVALID_SELECTOR" | "INVALID_REPRODUCER" | "OUTSIDE_7_DAY_WINDOW" | null;
  runId?: string | null;
  outcome?: TraceOutcome;
  leaks?: Array<{ path: string; code: "FORBIDDEN_FIELD" | "SECRET_PATTERN" }>;
};

export type ConversionResult = {
  sample: EvalSample | null;
  diagnostic: ConversionDiagnostic;
};

export type BatchConversionResult = {
  samples: EvalSample[];
  diagnostics: ConversionDiagnostic[];
};

export type RedactionValidation = {
  valid: boolean;
  code: ConversionDiagnostic["code"];
  leaks: Array<{ path: string; code: "FORBIDDEN_FIELD" | "SECRET_PATTERN" }>;
};

export const TRACE_TO_EVAL_SAMPLE_KINDS: readonly ["scenario", "route", "command-id"];

export function convertTraceToEvalSample(
  trace: SelectedTrace,
  options?: { now?: Date | string | number },
): ConversionResult;

export function convertSelectedTraces(
  traces: SelectedTrace[],
  options?: { now?: Date | string | number },
): BatchConversionResult;

export function validateTraceRedaction(trace: SelectedTrace): RedactionValidation;

export function computeSampleDigest(sample: EvalSample): string;
