  /\bghp_[A-Za-z0-9]{8,}\b/,
  /\bAKIA[0-9A-Z]{12,}\b/,
  /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/,
];

const REPRODUCER_KINDS = new Set(["scenario", "route", "command-id"]);
const TRAJECTORY_STATES = new Set(["failure", "success", "rejected", "cancelled"]);

function canonicalJson(value) {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(",")}}`;
}

function digest(value) {
  return `sha256:${createHash("sha256").update(canonicalJson(value)).digest("hex")}`;
}

function normalizedKey(key) {
  return String(key).toLowerCase().replace(/[-_]/g, "");
}

function findLeak(value, path = "$", found = []) {
  if (Array.isArray(value)) {
    value.forEach((item, index) => findLeak(item, `${path}[${index}]`, found));
    return found;
  }
  if (!value || typeof value !== "object") return found;
  for (const [key, child] of Object.entries(value)) {
    const nextPath = `${path}.${key}`;
    const normalized = normalizedKey(key);
    if (FORBIDDEN_KEYS.includes(normalized)) found.push({ path: nextPath, code: "FORBIDDEN_FIELD" });
    findLeak(child, nextPath, found);
  }
  return found;
}

function findSecret(value, path = "$", found = []) {
  if (typeof value === "string") {
    if (SECRET_PATTERNS.some((pattern) => pattern.test(value))) {
      found.push({ path, code: "SECRET_PATTERN" });
    }
    return found;
  }
  if (Array.isArray(value)) {
    value.forEach((item, index) => findSecret(item, `${path}[${index}]`, found));
    return found;
  }
  if (!value || typeof value !== "object") return found;
  for (const [key, child] of Object.entries(value)) findSecret(child, `${path}.${key}`, found);
  return found;
